#include "test_common.h"
#include "vmx_ept_hook_transaction.h"
#include <string.h>
#define R UINT64_C(1)
#define W UINT64_C(2)
#define X UINT64_C(4)
#define WB (UINT64_C(6)<<3)
#define LP (UINT64_C(1)<<7)
#define A (UINT64_C(1)<<8)
static int test_plan_and_transaction(void){uint64_t e[VMX_EPT_HOOK_PTE_COUNT];VMX_EPT_HOOK_PLAN p={0};VMX_EPT_HOOK_RECORD r={0};uint64_t parent=UINT64_C(0x400000)|R|W|X|WB|LP|A;TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x412000),(uint8_t)(R|W),parent,UINT64_C(0x9000),e,&p),VMX_EPT_HOOK_OK,"plan");TEST_ASSERT_TRUE(VmxEptHookPlanValid(&p),"valid");TEST_ASSERT_UINT_EQ(p.TargetIndex,0x12,"index");TEST_ASSERT_UINT_EQ(p.ReplacementParentEntry,UINT64_C(0x9000)|R|W|X|A,"parent");TEST_ASSERT_UINT_EQ(p.OriginalTargetEntry,UINT64_C(0x412000)|R|W|X|WB|A,"original");TEST_ASSERT_UINT_EQ(p.HookedTargetEntry,UINT64_C(0x412000)|X|WB|A,"hooked");TEST_ASSERT_UINT_EQ(e[0x12],p.HookedTargetEntry,"emitted");TEST_ASSERT_INT_EQ(VmxEptHookPrepare(&p,9,&r),VMX_EPT_HOOK_OK,"prepare");TEST_ASSERT_INT_EQ(VmxEptHookCommit(&r,p.ReplacementParentEntry,p.HookedTargetEntry),VMX_EPT_HOOK_OK,"commit");TEST_ASSERT_INT_EQ(VmxEptHookBeginRollback(&r,10),VMX_EPT_HOOK_OK,"rollback");TEST_ASSERT_INT_EQ(VmxEptHookCompleteRollback(&r,p.OriginalParentEntry,p.OriginalTargetEntry),VMX_EPT_HOOK_OK,"complete");TEST_ASSERT_TRUE(VmxEptHookRecordValid(&r),"free valid");return 0;}
static int test_fail_closed(void){uint64_t e[VMX_EPT_HOOK_PTE_COUNT],before[VMX_EPT_HOOK_PTE_COUNT];VMX_EPT_HOOK_PLAN p,pb;VMX_EPT_HOOK_RECORD r={0},rb;uint64_t parent=UINT64_C(0x200000)|R|W|X|WB|LP;memset(e,0xa5,sizeof(e));memcpy(before,e,sizeof(e));memset(&p,0x5a,sizeof(p));pb=p;TEST_ASSERT_TRUE(VmxEptHookPlan2Mb(UINT64_C(0x201001),(uint8_t)R,parent,UINT64_C(0x9000),e,&p)!=VMX_EPT_HOOK_OK,"unaligned");TEST_ASSERT_TRUE(memcmp(e,before,sizeof(e))==0,"entries preserved");TEST_ASSERT_TRUE(memcmp(&p,&pb,sizeof(p))==0,"plan preserved");memset(&p,0,sizeof(p));TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x201000),(uint8_t)R,parent,UINT64_C(0x9000),e,&p),VMX_EPT_HOOK_OK,"plan");TEST_ASSERT_INT_EQ(VmxEptHookPrepare(&p,1,&r),VMX_EPT_HOOK_OK,"prepare");rb=r;TEST_ASSERT_INT_EQ(VmxEptHookCommit(&r,p.OriginalParentEntry,p.HookedTargetEntry),VMX_EPT_HOOK_INVARIANT,"commit invariant");TEST_ASSERT_TRUE(memcmp(&r,&rb,sizeof(r))==0,"record preserved");TEST_ASSERT_INT_EQ(VmxEptHookAbortPrepare(&r,p.ReplacementParentEntry),VMX_EPT_HOOK_INVARIANT,"abort invariant");TEST_ASSERT_INT_EQ(VmxEptHookAbortPrepare(&r,p.OriginalParentEntry),VMX_EPT_HOOK_OK,"abort");TEST_ASSERT_INT_EQ(VmxEptHookPrepare(&p,0,&r),VMX_EPT_HOOK_INVALID,"generation");return 0;}
static int test_bounds(void){uint64_t e[VMX_EPT_HOOK_PTE_COUNT];VMX_EPT_HOOK_PLAN p={0};uint64_t parent=UINT64_C(0x600000)|R|W|WB|LP;TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x801000),(uint8_t)R,parent,UINT64_C(0xa000),e,&p),VMX_EPT_HOOK_UNSUPPORTED,"outside");TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x601000),0,parent,UINT64_C(0xa000),e,&p),VMX_EPT_HOOK_INVALID,"zero trap");TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x601000),UINT8_C(8),parent,UINT64_C(0xa000),e,&p),VMX_EPT_HOOK_INVALID,"unknown trap");TEST_ASSERT_INT_EQ(VmxEptHookPlan2Mb(UINT64_C(0x601000),(uint8_t)X,parent,UINT64_C(0xa000),e,&p),VMX_EPT_HOOK_INVALID,"absent permission");return 0;}
int main(void){TEST_RUN(test_plan_and_transaction);TEST_RUN(test_fail_closed);TEST_RUN(test_bounds);return 0;}
